SELECT COUNT(DISTINCT session_id) AS sessionCount, COALESCE(SUM(TIMESTAMPDIFF(SECOND, start_time, end_time)) / 60, 0) AS duration, COALESCE(SUM(view_count), 0) AS viewCount, COALESCE(SUM(sales_revenue), 0) AS salesRevenue, COALESCE(SUM(refund), 0) AS refund, COALESCE(SUM(net_sales), 0) AS netSales, COALESCE(SUM(investment), 0) AS investment FROM session_performance WHERE tenant_id = #{tenantId} AND stats_date BETWEEN #{startDate} AND #{endDate} AND is_deleted = 0
AND
company_id dept_id team_id live_room_id company_id = #{sourceId}
